def bell_number(n):
    """Calculate the Bell number for a given set size n."""
    # Initialize a list to store the Bell numbers
    bell = [0] * (n + 1)
    bell[0] = 1  # The Bell number for an empty set is 1

    # Calculate the Bell numbers using the recursive formula
    for i in range(1, n + 1):
        for j in range(i):
            bell[i] += bell[j] * bell[i - j - 1]

    return bell[n]

def is_Monotonic(arr):
    """
    Check if the array is monotonic. An array is monotonic if it is either entirely non-increasing or non-decreasing.
    """
    if not arr:
        return True  # An empty array is considered monotonic

    increasing = decreasing = True

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            decreasing = False
        elif arr[i] < arr[i - 1]:
            increasing = False

    return increasing or decreasing

